var _ = runtime.SetFinalizer

type Token_SinkCallback interface {
	OnPiece(piece string) error
}

type Token_SinkCallbackDefaults struct{}

func (Token_SinkCallbackDefaults) OnPiece(piece string) error { return nil }

type token_SinkCallbackAdapter struct {
	impl Token_SinkCallback
}

func (a *token_SinkCallbackAdapter) HandleCallback(methodID int32, req []byte) ([]byte, error) {
	switch methodID {
	case 0: // OnPiece
		var piece string
		_r := &pbReader{data: req}
		for _f, _w, _ok := _r.next(); _ok; _f, _w, _ok = _r.next() {
			switch _f {
			case 1:
				piece = _r.readString()
			default:
				_r.skip(_w)
			}
		}
		err := a.impl.OnPiece(piece)
		if err != nil {
			return nil, err
		}
		return nil, nil
	}
	return nil, fmt.Errorf("unknown callback method %d", methodID)
}

