var _ = fmt.Errorf
var _ = runtime.SetFinalizer

type Token_Sink struct {
	ptr       uint64
	keepAlive []any
}

func (h *Token_Sink) rawPtr() uint64 { return h.ptr }

func (h *Token_Sink) setKeepAlive(v any) {
	if h != nil && v != nil {
		h.keepAlive = append(h.keepAlive, v)
	}
}

func (h *Token_Sink) clearPtr() {
	if h != nil {
		h.ptr = 0
	}
}

func (*Token_Sink) isToken_Sink() {}

func newToken_Sink(ptr uint64) *Token_Sink {
	h := &Token_Sink{ptr: ptr}
	runtime.SetFinalizer(h, (*Token_Sink).free)
	return h
}

func newToken_SinkNoFinalizer(ptr uint64) *Token_Sink {
	h := &Token_Sink{ptr: ptr}
	return h
}

func (h *Token_Sink) OnPiece(piece string) error {
	buf := pbAppendHandle(pbNewBuf(), 1, h.ptr)
	buf = pbAppendString(buf, 2, piece)
	_, err := invokeMethod(1, 0, buf, wasm2go.Inv_1_0)
	return err
}

func NewToken_SinkFromImpl(impl Token_SinkCallback) (*Token_Sink, error) {
	adapter := &token_SinkCallbackAdapter{impl: impl}
	id := RegisterCallback(adapter)
	buf := pbNewBuf()
	buf = pbAppendInt32(buf, 1, id)
	resp, err := invokeMethod(1, 1, buf, wasm2go.Inv_1_1)
	if err != nil {
		UnregisterCallback(id)
		return nil, err
	}
	h := newToken_Sink(readScalarAtField(resp, 1, (*pbReader).readUint64))
	runtime.SetFinalizer(h, nil)
	runtime.SetFinalizer(h, func(h *Token_Sink) { h.free(); UnregisterCallback(id) })
	return h, nil
}

func (h *Token_Sink) free() {
	if h.ptr != 0 {
		buf := pbAppendHandle(pbNewBuf(), 1, h.ptr)
		module().invoke(1, 2, buf, wasm2go.Inv_1_2)
		h.ptr = 0
	}
}

