// Apply the model's chat template to `messages_json`
// (`[{"role":"user","content":"hi"}, ...]`) and return the prompt string:
// `{"ok":true,"prompt":"..."}`. `add_assistant` appends the generation
// prefix. When the GGUF carries no template, `template_override` is used;
// when both are absent the call fails.
func LlamaChatApplyTemplate(model uint64, messagesJson string, messagesJsonLen uint32, templateOverride string, templateOverrideLen uint32, addAssistant int32) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, model)
	buf = pbAppendString(buf, 2, messagesJson)
	buf = pbAppendUint64(buf, 3, uint64(messagesJsonLen))
	buf = pbAppendString(buf, 4, templateOverride)
	buf = pbAppendUint64(buf, 5, uint64(templateOverrideLen))
	buf = pbAppendInt32(buf, 6, addAssistant)
	resp, err := invokeMethod(0, 0, buf, wasm2go.Inv_0_0)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// Rebuild and attach the context's ggml threadpool. An instance forked
//
//	from a snapshot inherits the memory image of a context whose pool
//	references worker threads of the snapshot builder; those threads do not
//	exist in this process, so the next decode (or the join inside
//	llama_ctx_free) would wait forever. Call this right after forking: it
//	creates a fresh pool with n_threads workers (poll=0, as llama_ctx_new)
//	and attaches it, ABANDONING the inherited pool struct -- its memory is
//	shared snapshot pages and its dead threads cannot be joined. n_threads
//
// <
// = 1 detaches instead, and the context's n_threads / n_threads_batch
//
//	are set to the pool size (1 when detached) so graphs actually use the
//	workers. Returns {"ok":true,"n_threads":N,"n_threads_batch":N} — the
//	counts the context now computes with — or an error object.
func LlamaCtxAttachThreadpool(ctx uint64, nThreads uint32) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, ctx)
	buf = pbAppendUint64(buf, 2, uint64(nThreads))
	resp, err := invokeMethod(0, 1, buf, wasm2go.Inv_0_1)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

