// length, embedding dimension, layer/head counts, rope type, vocabulary size,
// and the chat template when the GGUF carries one.
func LlamaModelInfo(model uint64) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, model)
	resp, err := invokeMethod(0, 20, buf, wasm2go.Inv_0_20)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// Load a GGUF model from `path` and return an opaque handle (0 on failure;
// call llama_wasm_last_error for the reason).
//
// `n_gpu_layers` is accepted and ignored — a wasm build has no GPU backend —
// so callers can pass a config through unchanged.
//
// `use_mmap` is likewise accepted for API symmetry: WASI has no usable mmap,
// so the loader always reads the file. Progress is reported through the
// progress flag described at llama_model_load_progress_addr.
func LlamaModelLoad(path string, pathLen uint32, nGpuLayers int32, useMmap int32) (uint64, error) {
	buf := pbNewBuf()
	buf = pbAppendString(buf, 1, path)
	buf = pbAppendUint64(buf, 2, uint64(pathLen))
	buf = pbAppendInt32(buf, 3, nGpuLayers)
	buf = pbAppendInt32(buf, 4, useMmap)
	resp, err := invokeMethod(0, 21, buf, wasm2go.Inv_0_21)
	if err != nil {
		return 0, err
	}
	return readScalarAtField(resp, 1, (*pbReader).readUint64), nil
}

// Address, in linear memory, of a float the loader updates with its progress
// (0.0 .. 1.0) while llama_model_load runs. A host thread can poll it to drive
// a progress bar. Valid for the lifetime of the wasm instance.
func LlamaModelLoadProgressAddr() (uint64, error) {
	buf := pbNewBuf()
	resp, err := invokeMethod(0, 22, buf, wasm2go.Inv_0_22)
	if err != nil {
		return 0, err
	}
	return readScalarAtField(resp, 1, (*pbReader).readUint64), nil
}

// JSON list of the model's weight tensors:
//
//	{"ok":true,"tensors":[{"name":"blk.0.attn_q.weight","type":"q4_K",
//	"ne":[1536,1536],"buffer":"CPU_REPACK","vec_dot_type":"q8_K"},...]}
//	buffer is the ggml backend buffer holding the tensor ("CPU_REPACK" when
//	the CPU backend repacked it for its GEMV/GEMM kernels, "CPU" otherwise),
//	vec_dot_type the activation type its dot product quantizes to.
func LlamaModelTensors(model uint64) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, model)
	resp, err := invokeMethod(0, 23, buf, wasm2go.Inv_0_23)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// The text piece a single token renders to, as JSON `{"ok":true,"text":".."}`.
// Byte-level tokens can render to invalid UTF-8 on their own; the caller is
// expected to accumulate pieces.
func LlamaTokenToPiece(model uint64, token int32, renderSpecial int32) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, model)
	buf = pbAppendInt32(buf, 2, token)
	buf = pbAppendInt32(buf, 3, renderSpecial)
	resp, err := invokeMethod(0, 24, buf, wasm2go.Inv_0_24)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// Tokenize `text` and return JSON `{"ok":true,"tokens":[..]}`.
// `add_special` adds BOS/EOS per the model's convention; `parse_special`
// lets special-token text (e.g. "<|im_start|>") tokenize as that token.
func LlamaTokenize(model uint64, text string, textLen uint32, addSpecial int32, parseSpecial int32) (string, error) {
	buf := pbNewBuf()
	buf = pbAppendUint64(buf, 1, model)
	buf = pbAppendString(buf, 2, text)
	buf = pbAppendUint64(buf, 3, uint64(textLen))
	buf = pbAppendInt32(buf, 4, addSpecial)
	buf = pbAppendInt32(buf, 5, parseSpecial)
	resp, err := invokeMethod(0, 25, buf, wasm2go.Inv_0_25)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

